import sys, json
import pandas as pd
import numpy as np

def to_float(x):
    if pd.isna(x):
        return None
    return float(round(x, 2))

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---- Totals ----
    rev_tw_sum = df['Revenue_TW'].sum(skipna=True)
    rev_lw_sum = df['Revenue_LW'].sum(skipna=True)
    rev_ly_sum = df['Revenue_LY'].sum(skipna=True)
    units_tw_sum = df['Units_TW'].sum(skipna=True)
    orders_tw_sum = df['Orders_TW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(rev_tw_sum),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(rev_lw_sum),
        "formula": "sum(Revenue_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LY",
        "value": to_float(rev_ly_sum),
        "formula": "sum(Revenue_LY)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(units_tw_sum),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(orders_tw_sum),
        "formula": "sum(Orders_TW)"
    })

    if rev_lw_sum and not pd.isna(rev_lw_sum) and rev_lw_sum != 0:
        wow_total = (rev_tw_sum - rev_lw_sum) / rev_lw_sum * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_float(wow_total),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if rev_ly_sum and not pd.isna(rev_ly_sum) and rev_ly_sum != 0:
        yoy_total = (rev_tw_sum - rev_ly_sum) / rev_ly_sum * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_float(yoy_total),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---- Top entities by rank (top 3) ----
    top_entities = df.dropna(subset=['Rank']).sort_values('Rank').head(3)

    for _, row in top_entities.iterrows():
        ent = row['Entity']
        if not pd.isna(row.get('Revenue_TW')):
            facts.append({
                "entity": ent, "metric": "revenue", "period": "TW",
                "value": to_float(row['Revenue_TW']),
                "formula": "Revenue_TW"
            })
        if not pd.isna(row.get('Share_Pct')):
            facts.append({
                "entity": ent, "metric": "share", "period": "TW",
                "value": to_float(row['Share_Pct']),
                "formula": "Share_Pct"
            })
        if not pd.isna(row.get('Rank')):
            facts.append({
                "entity": ent, "metric": "rank", "period": "TW",
                "value": to_float(row['Rank']),
                "formula": "Rank"
            })
        if not pd.isna(row.get('WoW_Pct')):
            facts.append({
                "entity": ent, "metric": "revenue", "period": "WoW",
                "value": to_float(row['WoW_Pct']),
                "formula": "WoW_Pct"
            })
        if not pd.isna(row.get('YoY_Pct')):
            facts.append({
                "entity": ent, "metric": "revenue", "period": "YoY",
                "value": to_float(row['YoY_Pct']),
                "formula": "YoY_Pct"
            })

    # ---- Biggest WoW gainer / loser ----
    wow_valid = df.dropna(subset=['WoW_Pct'])
    if not wow_valid.empty:
        gainer = wow_valid.loc[wow_valid['WoW_Pct'].idxmax()]
        loser = wow_valid.loc[wow_valid['WoW_Pct'].idxmin()]
        facts.append({
            "entity": gainer['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(gainer['WoW_Pct']),
            "formula": "max(WoW_Pct) - top WoW gainer"
        })
        facts.append({
            "entity": loser['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(loser['WoW_Pct']),
            "formula": "min(WoW_Pct) - top WoW loser"
        })

    # ---- Biggest YoY gainer / loser ----
    yoy_valid = df.dropna(subset=['YoY_Pct'])
    if not yoy_valid.empty:
        gainer_y = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmax()]
        loser_y = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmin()]
        facts.append({
            "entity": gainer_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(gainer_y['YoY_Pct']),
            "formula": "max(YoY_Pct) - top YoY gainer"
        })
        facts.append({
            "entity": loser_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(loser_y['YoY_Pct']),
            "formula": "min(YoY_Pct) - top YoY loser"
        })

    # ---- Top entity by units and orders ----
    if df['Units_TW'].notna().any():
        top_units = df.loc[df['Units_TW'].idxmax()]
        facts.append({
            "entity": top_units['Entity'], "metric": "units", "period": "TW",
            "value": to_float(top_units['Units_TW']),
            "formula": "max(Units_TW)"
        })

    if df['Orders_TW'].notna().any():
        top_orders = df.loc[df['Orders_TW'].idxmax()]
        facts.append({
            "entity": top_orders['Entity'], "metric": "orders", "period": "TW",
            "value": to_float(top_orders['Orders_TW']),
            "formula": "max(Orders_TW)"
        })

    # Trim to 25 facts max
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
